import React, { useState } from 'react';
import { GoogleOAuthProvider } from '@react-oauth/google';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';

// Component Imports
import LoginPage from './components/LoginPage';
import HomePage from './components/HomePage';
import Clipper from './components/Clipper';
import SEO from './components/Seo';
import ClipperPage from './components/ClipperPage'; // New Page Import
import NotFoundPage from './components/NotFoundPage'; // Optional Page Not Found Component

const App = () => {
  // State Management: Centralized for app-wide data flow
  const [videoUrl, setVideoUrl] = useState('');
  const [videoThumbnail, setVideoThumbnail] = useState('');
  const [videoId, setVideoId] = useState('');

  return (
    <GoogleOAuthProvider clientId={process.env.REACT_APP_GOOGLE_CLIENT_ID}>
      <BrowserRouter>
        <Routes>
          {/* Public Route: Login Page */}
          <Route path="/" element={<LoginPage />} />

          {/* Home Page */}
          <Route
            path="/home"
            element={
              <HomePage
                setVideoUrl={setVideoUrl}
                setVideoThumbnail={setVideoThumbnail}
                setVideoId={setVideoId}
              />
            }
          />

          {/* Clipper Page */}
          <Route
            path="/clipper"
            element={
              <Clipper
                videoUrl={videoUrl}
                setVideoUrl={setVideoUrl}
                videoThumbnail={videoThumbnail}
              />
            }
          />

          {/* Clipper Details Page */}
          <Route
            path="/clipper/details"
            element={
              <ClipperPage
                videoUrl={videoUrl}
                videoThumbnail={videoThumbnail}
              />
            }
          />

          {/* SEO Page */}
          <Route
            path="/seo"
            element={
              <SEO
                videoId={videoId}
                videoThumbnail={videoThumbnail}
              />
            }
          />

          {/* Redirect Invalid Paths to Home */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </GoogleOAuthProvider>
  );
};

export default App;
